        static readonly Dictionary<string,Geometry> cache=new Dictionary<string,Geometry>(StringComparer.Ordinal);
        internal static IEnumerable<string> Names { get { return data.Keys; } }
        internal static bool Has(string name) { return name!=null&&data.ContainsKey(name); }
        // Raw path data (read-only table, safe from any thread), for renderers outside the WPF dispatcher.
        internal static string PathData(string name) { string path;return name!=null&&data.TryGetValue(name,out path)?path:null; }
        // Geometry scaled to the requested square size. The pen is applied after the transform, so stroke width stays in pixels.
        internal static Geometry Geometry(string name,double size) {
            string key=name+"@"+size.ToString(System.Globalization.CultureInfo.InvariantCulture);Geometry geometry;
            if(cache.TryGetValue(key,out geometry))return geometry;
            string path;if(!data.TryGetValue(name,out path))path=data["circle-help"];
            geometry=System.Windows.Media.Geometry.Parse(path).Clone();
            geometry.Transform=new ScaleTransform(size/24,size/24);geometry.Freeze();cache[key]=geometry;return geometry;
        }
        // Icon that follows the inherited foreground unless an explicit ink is given.
        internal static Path Create(string name,double size=18,Brush ink=null,double stroke=0) {
            var icon=new Path { Data=Geometry(name,size),Width=size,Height=size,StrokeThickness=stroke>0?stroke:Math.Max(1.25,size/12),
                StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,StrokeLineJoin=PenLineJoin.Round,
                SnapsToDevicePixels=false,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,IsHitTestVisible=false };
            if(ink!=null)icon.Stroke=ink;
            else icon.SetBinding(Shape.StrokeProperty,new Binding { Path=new PropertyPath(TextElement.ForegroundProperty),RelativeSource=RelativeSource.Self });
            return icon;
        }
        // Drawing for DrawingContext users (map markers, cached POI stamps).
        internal static void Draw(DrawingContext dc,string name,Point centre,double size,Brush ink,double stroke=0) {
            var pen=new Pen(ink,stroke>0?stroke:Math.Max(1.25,size/12)) { StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round,LineJoin=PenLineJoin.Round };pen.Freeze();
            dc.PushTransform(new TranslateTransform(centre.X-size/2,centre.Y-size/2));dc.DrawGeometry(null,pen,Geometry(name,size));dc.Pop();
        }
